import{_ as r,l as o,o as e,c as n,v as l,p as s,x as t,d as E,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"掩模加热","description":"","frontmatter":{"title":"掩模加热","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/reticle-heating.md","filePath":"litho/reticle-heating.md","lastUpdated":1789023840000}'),d={name:"litho/reticle-heating.md"};function c(A,a,B,_,m,u){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="掩模加热" tabindex="-1">掩模加热 <a class="header-anchor" href="#掩模加热" aria-label="Permalink to &quot;掩模加热&quot;">​</a></h1><div class="epigraph"><p>掩模吸收的那一截曝光能量会变成温度场；石英或多层膜一胀，图形在物面挪动，套刻指纹跟着扫描热量走。</p><footer>—— 据 ASML 等对 overlay 热贡献源的公开论述：掩模（reticule）加热是独立于工件台的一项</footer></div><p><a href="/litho/alignment-spm">上一课</a>把曝光前网格钉在晶圆标记与 SPM 上。缺口是曝光期间掩模自己在热：吸收体和膜堆吃光，热膨胀进套刻，对准再密也测不到这块——它发生在物面。本课钉掩模加热。晶圆侧的曝光热与卡盘冷却留给[下一课](/litho/wafer-thermal-overlay）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描机把高功率准分子或 EUV 打到掩模上。透射版的铬/MoSi 吸一部分；EUV 反射版的吸收体和多层膜也吸一部分。热量沿版扩散、向 pellicle 和周围辐射，温度场随场内容图形密度和时间变。石英（或 EUV 基板）热胀系数虽小，乘上 4× 物面尺寸，落到晶圆上仍是纳米级放大与畸变。</p><p>上一课的对准在晶圆侧。掩模台有自己的对准与夹持，但温度场在扫描开始后还在爬，稳态与第一场不同。把「前几片套刻差」写成晶圆翘曲，会漏掉掩模瞬态。</p><h3 id="加热不是镜头像差" tabindex="-1">加热不是镜头像差 <a class="header-anchor" href="#加热不是镜头像差" aria-label="Permalink to &quot;加热不是镜头像差&quot;">​</a></h3><p>镜头有热像差和 ILLIAS 一类校正；掩模加热是物面几何。两者都随时间变，校正旋钮不同。混在「热 overlay」一个桶里，会去拧错的补偿表。</p><p><span class="marginnote">图形疏密不同的版，热指纹不同。同一台机器、同一剂量，换版就能换 overlay 形状。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开治理分三层。减吸收：EUV 高透过 pellicle、更优吸收体，让热量少进基板。均热与等待：让版在曝光功率下接近准稳态再跑产品，或用前几场专用校正。模型补偿：按剂量、扫描方向和版的热模型预畸变曝光网格，或场间更新。ASML 套刻叙事把掩模加热与晶圆加热、镜头漂移并列，而不是单一「热」开关。</p><p>计量：用套刻标记读到的放大、偏扭，要分层归因——掩模热往往沿扫描方向有特征时间，换卡盘实验可以和晶圆热拆开。本课不写未公开的毫开尔文或纳米表。</p>',12)),(e(),s(h,null,{default:t(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOSE%5B%22%E6%9B%9D%E5%85%89%E5%8A%9F%E7%8E%87%22%5D%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%20%2F%20%E5%A4%9A%E5%B1%82%E8%86%9C%E5%90%B8%E7%83%AD%22%5D%0A%20%20ABS%20--%3E%20T%5B%22%E6%8E%A9%E6%A8%A1%E6%B8%A9%E5%BA%A6%E5%9C%BA%22%5D%0A%20%20T%20--%3E%20EXP%5B%22%E5%9F%BA%E6%9D%BF%E7%83%AD%E8%83%80%22%5D%0A%20%20EXP%20--%3E%20OV%5B%22%E7%89%A9%E9%9D%A2%E5%9B%BE%E5%BD%A2%E4%BD%8D%E7%A7%BB%20%E2%86%92%20%E5%A5%97%E5%88%BB%22%5D%0A%20%20COR%5B%22%E5%9D%87%E7%83%AD%20%2F%20%E6%A8%A1%E5%9E%8B%E9%A2%84%E8%A1%A5%E5%81%BF%22%5D%20--%3E%20OV%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h3 id="euv-与-duv-的热路径不同" tabindex="-1">EUV 与 DUV 的热路径不同 <a class="header-anchor" href="#euv-与-duv-的热路径不同" aria-label="Permalink to &quot;EUV 与 DUV 的热路径不同&quot;">​</a></h3><p>DUV 透射，热量在吸收图案与石英里；EUV 反射，热量在多层与吸收体，还要过真空与 pellicle 气载约束。pellicle 自己也热、也胀，会改有效透过和局部波前，但首先仍是剂量与污染项。不要把 pellicle 课整段搬来；这里只承认 EUV 掩模热路径更长。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>热胀把掩模坐标变成时间的函数。4× 缩比把物面位移缩到晶圆，但物面尺度大，净 overlay 仍可观。扫描狭缝下的局部加热随瞬时图形密度变，密金属版比稀疏植入版热得狠。瞬态：第一批场在爬温，套刻放大项漂移；稳态：形成与冷却平衡的指纹，仍可能随环境与流量变。</p><p>对准网格若只在晶圆上加密，补偿不了物面在动。必须把掩模台位置、版夹持和热模型放进同一套刻预算，见 overlay 贡献源分解的公开分法：设备、掩模、工艺。掩模热跨设备和掩模两栏。</p><p><span class="marginnote">MEF 放大的是掩模 CD 误差；热胀放大的是掩模位置。两个「掩模贡献」不要加进同一个纳米。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要发明某国产掩模台的热控指标。不要把镜头热像差的 Zernike 校正当成已经修好掩模胀。本课不重写 pellicle 材料。晶圆热是下一课：卡盘、浸没水和曝光剂量在硅片上的温度场，指纹形状与掩模热不同，拆不开就谈不上 holistic overlay。曝光功率一改，两套热源都会动，实验必须换版与换剂量交叉，不能只看一场套刻放大项。</p><p><span class="marginnote">出处：ASML 对 overlay 热源（含 reticle heating）的公开产品与 SPIE 论述。不编造未公布的掩模温升曲线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>掩模吸收曝光能量，热胀进入套刻，对准网格测的是晶圆不是这块物面瞬态。</li><li>与镜头热像差、晶圆热是不同贡献源。</li><li>减吸收、均热、模型补偿是公开的三层治理。</li><li>图形密度决定热指纹，换版即换形状。</li><li>晶圆热套刻下一课。</li><li>出处：ASML overlay 热源公开论述。</li></ul>',11))])}const S=r(d,[["render",c]]);export{f as __pageData,S as default};
